				function getHeadings() {
					return [{"depth":2,"slug":"the-diy-direct-mail-reality","text":"The DIY Direct Mail Reality"},{"depth":3,"slug":"what-diy-looks-like-in-practice","text":"What DIY Looks Like in Practice"},{"depth":3,"slug":"what-mail-house-processing-costs-for-the-same-campaign","text":"What Mail House Processing Costs for the Same Campaign"},{"depth":3,"slug":"the-comparison","text":"The Comparison"},{"depth":2,"slug":"when-diy-actually-makes-sense","text":"When DIY Actually Makes Sense"},{"depth":3,"slug":"very-small-quantities-under-200-pieces","text":"Very Small Quantities (Under 200 Pieces)"},{"depth":3,"slug":"simple-first-class-postcard-campaigns","text":"Simple First-Class Postcard Campaigns"},{"depth":3,"slug":"test-campaigns-before-committing","text":"Test Campaigns Before Committing"},{"depth":2,"slug":"what-to-ask-a-mail-house","text":"What to Ask a Mail House"},{"depth":2,"slug":"the-hidden-costs-of-diy-that-the-spreadsheet-doesnt-show","text":"The Hidden Costs of DIY That the Spreadsheet Doesn’t Show"},{"depth":2,"slug":"hybrid-approaches-when-partial-diy-works","text":"Hybrid Approaches: When Partial DIY Works"},{"depth":2,"slug":"the-decision-framework","text":"The Decision Framework"}];
				}

				const Content = createComponent((result, _props, slots) => {
					const { layout, ...content } = frontmatter;
					content.file = file;
					content.url = url;

					return renderTemplate`${maybeRenderHead()}${unescapeHTML(html)}`;
				});

export { Content, compiledContent, Content as default, file, frontmatter, getHeadings, rawContent, url };
